namespace ShinyCommander.Services;

/// <summary>
/// Persistent settings. Each [Bind] property is source generated by Shiny.Extensions.DependencyInjection to
/// read/write through Shiny.Extensions.Stores (NSUserDefaults on macOS, LocalSettings / a JSON file on
/// Windows, a JSON file under XDG on Linux).
/// </summary>
[Singleton]
public partial class AppSettings
{
    [Bind] public partial bool ShowHidden { get; set; }
    [Bind] public partial bool ConfirmDelete { get; set; }
    [Bind] public partial bool UseTrash { get; set; }
    [Bind] public partial bool FriendlySizes { get; set; }
    [Bind] public partial bool ExtractToFolderPerArchive { get; set; }
    [Bind] public partial bool OpenFoldersInNewTabOnMiddle { get; set; }
    [Bind] public partial string? Theme { get; set; }
    [Bind] public partial string? ExternalEditor { get; set; }
    [Bind] public partial int ViewerFontSize { get; set; }
    [Bind] public partial int PanelFontSize { get; set; }

    /// <summary>Tab paths per side separated by newlines - restored on startup.</summary>
    [Bind] public partial string? LeftTabs { get; set; }
    [Bind] public partial string? RightTabs { get; set; }
    [Bind] public partial int LeftActiveTab { get; set; }
    [Bind] public partial int RightActiveTab { get; set; }
    [Bind] public partial bool RightPanelActive { get; set; }

    /// <summary>Directory hotlist (Ctrl+D) - newline separated.</summary>
    [Bind] public partial string? Hotlist { get; set; }

    [Bind] public partial bool HasInitialized { get; set; }

    public void EnsureDefaults()
    {
        if (this.HasInitialized)
            return;

        this.ConfirmDelete = true;
        this.UseTrash = true;
        this.FriendlySizes = false;
        this.ExtractToFolderPerArchive = true;
        this.Theme = "System";
        this.ViewerFontSize = 13;
        this.PanelFontSize = 13;
        this.HasInitialized = true;
    }

    public static IReadOnlyList<string> SplitLines(string? value)
        => String.IsNullOrWhiteSpace(value) ? [] : value.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

    public static string JoinLines(IEnumerable<string> values) => String.Join('\n', values);
}
